export type BibleEdition = (typeof BIBLE_EDITIONS)[number];
export type AvailableLocale = BibleEdition['locale'];
export const getAvailableEditions = () => BIBLE_EDITIONS;
export function getBibleEdition(id?: string | null): BibleEdition {
  return BIBLE_EDITIONS.find((edition) => edition.id === id) || BIBLE_EDITIONS[0];
}
export function isAvailableEdition(id: unknown): id is BibleEdition['id'] {
  return BIBLE_EDITIONS.some((edition) => edition.id === id);
}
export function canonicalBook(book: string): string | undefined {
  return Object.keys(bibleBookChapterCounts).find(
    (key) => key.toLowerCase() === book.trim().toLowerCase(),
  );
}
/** Explicit existing source gaps; keep the edition available for its converted books. */
export function editionHasBook(book: string, translation: string): boolean {
  const key = canonicalBook(book);
  return (
    !!key &&
    !(
      translation === 'id-tsi' &&
      [
        'leviticus',
        'numbers',
        'joshua',
        'judges',
        'firstKings',
        'secondKings',
        'firstChronicles',
        'secondChronicles',
        'job',
        'psalms',
        'solomon',
        'isaiah',
        'jeremiah',
        'lamentations',
        'ezekiel',
        'daniel',
        'hosea',
        'joel',
        'amos',
        'obadiah',
        'micah',
        'nahum',
        'habakkuk',
        'zephaniah',
        'haggai',
        'zechariah',
        'malachi',
      ].includes(key)
    )
  );
}
export function editionChapterCount(book: string, translation = 'kjv'): number {
  const key = canonicalBook(book);
  if (translation === 'lut' && key === 'malachi') {
    return 3;
  }
  return key ? bibleBookChapterCounts[key] : 0;
}
export function bibleAssetUrls(translation: string, path: string): string[] {
  const folder = getBibleEdition(translation).folder;
  const asset = `bibles/${folder}/${path}`;
  return [
    `https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api@${BIBLE_REVISION}/${asset}`,
    `https://raw.githubusercontent.com/revelationaryonline/bible-api/${BIBLE_REVISION}/${asset}`,
  ];
}
export function bibleChapterUrls(translation: string, book: string, chapter: number): string[] {
  const key = canonicalBook(book);
  if (
    !isAvailableEdition(translation) ||
    !key ||
    !editionHasBook(book, translation) ||
    !Number.isInteger(chapter) ||
    chapter < 1 ||
    chapter > editionChapterCount(key, translation)
  ) {
    throw new Error('Unsupported Bible passage');
  }
  // The Spanish repository uses camelCase folders. Other converted editions use lowercase.
  const folder = translation === 'es-rv09' ? key : key.toLowerCase();
  return bibleAssetUrls(translation, `books/${folder}/chapters/${chapter}.json`);
}
