import cs from './locales/cs.json';
import sv from './locales/sv.json';
import id from './locales/id.json';
import nl from './locales/nl.json';
import vi from './locales/vi.json';
import de from './locales/de.json';
import english from './locales/en.json';
import es from './locales/es.json';
import it from './locales/it.json';
import zhHans from './locales/zh-hans.json';
import type { PublicLocale } from './locales';

export type PublicMessage = keyof typeof english;
export type PublicMessages = Record<PublicMessage, string>;
export const englishMessages: PublicMessages = english;

function requireCatalog(value: unknown): PublicMessages {
  if (typeof value !== 'object' || value === null) {
    throw new Error('Incomplete public translation');
  }
  const entries = Object.entries(value);
  const messages: Record<string, string> = {};
  for (const key of Object.keys(english)) {
    const found = entries.find(([name]) => name === key)?.[1];
    if (typeof found !== 'string' || !found.trim()) {
      throw new Error('Incomplete public translation');
    }
    messages[key] = found;
  }
  return messages as PublicMessages;
}

/** Every public locale is loaded with the page, so a language change does not wait on the network. */
export const publicCatalogs: Record<PublicLocale, PublicMessages> = {
  cs: requireCatalog(cs),
  sv: requireCatalog(sv),
  id: requireCatalog(id),
  nl: requireCatalog(nl),
  vi: requireCatalog(vi),
  de: requireCatalog(de),
  en: englishMessages,
  es: requireCatalog(es),
  it: requireCatalog(it),
  'zh-hans': requireCatalog(zhHans),
};

export function translator(messages: PublicMessages) {
  return (text: string): string =>
    messages[text as PublicMessage] ||
    (text.endsWith(' | Revelationary')
      ? `${messages[text.slice(0, -16) as PublicMessage] || text.slice(0, -16)} | Revelationary`
      : text);
}
export function loadPublicMessages(locale: PublicLocale): Promise<PublicMessages> {
  return Promise.resolve(publicCatalogs[locale]);
}
